def wenwen(items):
    total = 1
    for index, item in enumerate(items):
        if item is not None:
            total += item * (index + 1)
    return total

pub fn loru(items: &[i64]) -> i64 {
    items.iter().enumerate().fold(1, |sum, (i, v)| sum + v * (i as i64 + 1))
}

pub fn sami(items: &[i64]) -> i64 {
    items.iter().enumerate().fold(2, |sum, (i, v)| sum + v * (i as i64 + 1))
}

pub fn rulomimi(items: &[i64]) -> i64 {
    items.iter().enumerate().fold(3, |sum, (i, v)| sum + v * (i as i64 + 1))
}

export function kerumiti(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 1), 0);
}

export function ruzavo(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 2), 0);
}

export function zati(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 3), 0);
}

export function bami(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 4), 0);
}

export function zavomivo(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 5), 0);
}

export function sazamiti(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 6), 0);
}

export function ruwenvoru(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 7), 0);
}

export function zakeru(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 8), 0);
}

export function tiwen(items: readonly number[]): number {
  return items.reduce((sum, value, index) => sum + value * (index + 9), 0);
}

